tAlong":0.5,"sourceInvisibleLeader":true,"targetInvisibleLeader":true,"waypoints":[{"x":80,"y":90},{"x":145,"y":90},{"x":169,"y":90},{"x":224,"y":90},{"x":247,"y":90},{"x":270,"y":90}]},{"id":"c1","sourceId":"g","targetId":"next","type":"sequence","directionType":"directed","routingType":"rectilinear","sourceSide":"right","targetSide":"left","sourceOffsetAlong":0.5,"targetOffsetAlong":0.5,"sourceInvisibleLeader":true,"targetInvisibleLeader":true,"waypoints":[{"x":270,"y":90},{"x":293,"y":90},{"x":316,"y":90},{"x":371,"y":90},{"x":395,"y":90},{"x":460,"y":90}],"label":"Yes"},{"id":"c2","sourceId":"g","targetId":"t","type":"sequence","directionType":"directed","routingType":"rectilinear","sourceSide":"right","targetSide":"left","sourceOffsetAlong":0.5,"targetOffsetAlong":0.5,"sourceInvisibleLeader":true,"targetInvisibleLeader":true,"waypoints":[{"x":270,"y":90},{"x":293,"y":90},{"x":297,"y":90},{"x":-22,"y":90},{"x":-22,"y":90},{"x":11,"y":90},{"x":15,"y":90},{"x":80,"y":90}],"label":"No"}]}$TJ$::jsonb, (SELECT id FROM "User" ORDER BY "createdAt" ASC LIMIT 1), now(), now()
