"sourceId":"t","targetId":"e","type":"sequence","directionType":"directed","routingType":"rectilinear","sourceSide":"right","targetSide":"left","sourceOffsetAlong":0.5,"targetOffsetAlong":0.5,"sourceInvisibleLeader":true,"targetInvisibleLeader":true,"waypoints":[{"x":270,"y":90},{"x":335,"y":90},{"x":359,"y":90},{"x":420,"y":90},{"x":440,"y":90},{"x":460,"y":90}]}]}$TJ$::jsonb, (SELECT id FROM "User" ORDER BY "createdAt" ASC LIMIT 1), now(), now()
